  1→import { inject, Injectable } from "@angular/core";
  2→import { HttpClient } from "@angular/common/http";
  3→import { Observable } from "rxjs";
  4→import { environment } from "./environment";
  5→import type { RoleDef } from "./scenario-api.service";
  6→
  7→export type { RoleDef as RoleInfo } from "./scenario-api.service";
  8→
  9→export interface DecisionOption {
 10→  id: string;
 11→  label: string;
 12→  score?: number;
 13→  role?: string | null;
 14→  targets_system?: boolean;
 15→}
 16→
 17→export interface ActiveDecision {
 18→  id: string;
 19→  event_id: string | null;
 20→  issue_id: string | null;
 21→  title: string;
 22→  description: string;
 23→  question_type: string;
 24→  options: DecisionOption[];
 25→  completion_mode: string;
 26→  target_roles: string[];
 27→  timeout_ms: number;
 28→  max_selections: number | null;
 29→  status: string;
 30→  opened_at_pt_ms: number;
 31→  closed_at_pt_ms: number | null;
 32→  recommendations: Record<string, string>;
 33→  selected_option_ids: string[];
 34→}
 35→
 36→export interface DecisionSubmission {
 37→  participant_id: string;
 38→  participant_name: string;
 39→  selected_options: string[] | null;
 40→  free_text: string | null;
 41→}
 42→
 43→export interface DecisionResponseItem {
 44→  id: number;
 45→  participant_name: string;
 46→  selected_options: string[] | null;
 47→  free_text: string | null;
 48→  score: number | null;
 49→  submitted_at: string;
 50→}
 51→
 52→export interface DecisionDetail {
 53→  id: number;
 54→  exercise_id: number;
 55→  issue_id: string;
 56→  title: string;
 57→  description: string;
 58→  question_type: string;
 59→  options: DecisionOption[] | null;
 60→  completion_mode: string;
 61→  status: string;
 62→  created_at: string;
 63→  closed_at: string | null;
 64→  responses: DecisionResponseItem[];
 65→}
 66→
 67→export interface ScenarioContext {
 68→  title: string;
 69→  description: string;
 70→  briefing: string;
 71→  objectives: string[];
 72→  rules: string[];
 73→  roles: RoleDef[];
 74→  score_tier_thresholds?: Record<string, number>;
 75→}
 76→
 77→@Injectable({ providedIn: "root" })
 78→export class DecisionApiService {
 79→  private readonly http = inject(HttpClient);
 80→  private readonly base = environment.apiBaseUrl;
 81→
 82→  /** Get open decisions from the engine */
 83→  getEngineDecisions(exerciseId: number): Observable<ActiveDecision[]> {
 84→    return this.http.get<ActiveDecision[]>(
 85→      `${this.base}/api/exercises/${exerciseId}/engine/decisions`,
 86→    );
 87→  }
 88→
 89→  /** Submit a response to a DB-persisted decision */
 90→  submitResponse(
 91→    decisionId: number,
 92→    submission: DecisionSubmission,
 93→  ): Observable<DecisionResponseItem> {
 94→    return this.http.post<DecisionResponseItem>(
 95→      `${this.base}/api/decisions/${decisionId}/responses`,
 96→      submission,
 97→    );
 98→  }
 99→
100→  /** Get decision details with all responses (for GM observation) */
101→  getDecisionDetail(decisionId: number): Observable<DecisionDetail> {
102→    return this.http.get<DecisionDetail>(
103→      `${this.base}/api/decisions/${decisionId}`,
104→    );
105→  }
106→
107→  /** List all decisions for an exercise */
108→  listDecisions(
109→    exerciseId: number,
110→    status?: string,
111→  ): Observable<DecisionDetail[]> {
112→    const params: Record<string, string | number> = { exercise_id: exerciseId };
113→    if (status) {
114→      params["status"] = status;
115→    }
116→    return this.http.get<DecisionDetail[]>(`${this.base}/api/decisions`, {
117→      params,
118→    });
119→  }
120→
121→  /** Submit an advisor recommendation on an open decision */
122→  submitRecommendation(
123→    exerciseId: number,
124→    decisionId: string,
125→    optionId: string,
126→    participantId: string,
127→    roleId?: string,
128→  ): Observable<unknown> {
129→    const body: Record<string, string> = {
130→      decision_id: decisionId,
131→      option_id: optionId,
132→      participant_id: participantId,
133→    };
134→    if (roleId) {
135→      body["role_id"] = roleId;
136→    }
137→    return this.http.post(
138→      `${this.base}/api/exercises/${exerciseId}/engine/decisions/recommend`,
139→      body,
140→    );
141→  }
142→
143→  /** Close a decision in the engine (GM or decision-maker action) */
144→  closeEngineDecision(
145→    exerciseId: number,
146→    decisionId: string,
