  for (const [key, recOptionId] of Object.entries(d.recommendations)) {
    if (recOptionId === optionId) {
      const roleId = extractRecRoleId(key);
      const role = roles.find((r) => r.id === roleId);
      result.push(role?.label ?? roleId.toUpperCase());
    }
  }
  return result;
}
