    const allRoles = this.store.context()?.roles ?? [];
    const advisorRolesList = allRoles.filter((r) => r.player_type === "advisor");
    const event = this.currentTurnEvent();
    const decision = this.activeDecisions()[0] ?? null;
    return buildRoleCards(
      advisorRolesList,
      event,
      decision,
      this.submittedRoles(),
      false,
      allRoles,
    );
