import { ComponentFixture, TestBed } from "@angular/core/testing";
import { Component, signal } from "@angular/core";
import { BoardColumnComponent } from "./board-column.component";

@Component({
  imports: [BoardColumnComponent],
  template: `
    <tfc-board-column
      [roleId]="roleId()"
      [roleLabel]="roleLabel()"
      [intel]="intel()"
      [status]="status()"
      [expanded]="expanded()"
      (headerClicked)="onHeaderClick()"
    >
      <ng-template #decisionZone>
        <div data-testid="decision-content">Decision here</div>
      </ng-template>
    </tfc-board-column>
  `,
})
class TestHost {
  readonly roleId = signal("ops");
  readonly roleLabel = signal("Operations Officer");
  readonly intel = signal<string | null>("Phishing detected on port 443");
  readonly status = signal<"intel" | "active" | "done">("active");
  readonly expanded = signal(false);
  headerClickCount = 0;
  onHeaderClick(): void {
    this.headerClickCount++;
  }
}

describe("BoardColumnComponent", () => {
  let fixture: ComponentFixture<TestHost>;
  let host: TestHost;

  beforeEach(async () => {
    await TestBed.configureTestingModule({
      imports: [TestHost],
    }).compileComponents();
    fixture = TestBed.createComponent(TestHost);
    host = fixture.componentInstance;
    fixture.detectChanges();
  });

  it("renders the column with role header", () => {
    expect(
      fixture.nativeElement.querySelector(".board-column"),
    ).toBeTruthy();
    expect(
      fixture.nativeElement
        .querySelector(".board-column__role-id")
        ?.textContent.trim(),
    ).toBe("OPS");
  });

  it("renders role label", () => {
    expect(
      fixture.nativeElement
        .querySelector(".board-column__role-label")
        ?.textContent.trim(),
    ).toBe("Operations Officer");
  });

  it("renders intel text in the intel zone", () => {
    expect(
      fixture.nativeElement
        .querySelector(".board-column__intel")
        ?.textContent.trim(),
    ).toContain("Phishing detected on port 443");
  });

  it("shows empty state when intel is null", () => {
    host.intel.set(null);
    fixture.detectChanges();

    const empty = fixture.nativeElement.querySelector(
      ".board-column__intel .board-column__empty",
    );
    expect(empty).toBeTruthy();
    expect(empty?.textContent.trim()).toContain("Waiting for next turn...");
  });

  it("projects decision zone content", () => {
    expect(
      fixture.nativeElement.querySelector("[data-testid='decision-content']"),
    ).toBeTruthy();
  });

  it("emits headerClicked on header click", () => {
    const header = fixture.nativeElement.querySelector(
      ".board-column__header",
    ) as HTMLElement;
    header.click();
    expect(host.headerClickCount).toBe(1);
  });
});

import {
  ChangeDetectionStrategy,
  Component,
  computed,
  contentChild,
  input,
  output,
  type TemplateRef,
} from "@angular/core";
import { NgTemplateOutlet, UpperCasePipe } from "@angular/common";
import { BadgeComponent } from "@aspect/ui";

@Component({
  selector: "tfc-board-column",
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [UpperCasePipe, NgTemplateOutlet, BadgeComponent],
  template: `
    <div class="board-column">
      <div class="board-column__header" (click)="headerClicked.emit()">
        <div>
          <span class="board-column__role-id">{{ roleId() | uppercase }}</span>
          <span class="board-column__role-label">{{ roleLabel() }}</span>
        </div>
        <ui-badge [variant]="badgeVariant()">{{ badgeLabel() }}</ui-badge>
      </div>

      <div class="board-column__intel">
        @if (intel()) {
          <div class="board-column__intel-text">{{ intel() }}</div>
        } @else {
          <div class="board-column__empty">Waiting for next turn...</div>
        }
      </div>

      <div class="board-column__decision">
        @if (decisionTpl(); as tpl) {
          <ng-container [ngTemplateOutlet]="tpl" />
        } @else {
          <div class="board-column__empty">No active decision</div>
        }
      </div>
    </div>
  `,
})
export class BoardColumnComponent {
  readonly roleId = input.required<string>();
  readonly roleLabel = input.required<string>();
  readonly intel = input<string | null>(null);
  readonly status = input<"intel" | "active" | "done">("intel");
  readonly expanded = input(false);

  readonly headerClicked = output<void>();

  readonly decisionTpl = contentChild<TemplateRef<unknown>>("decisionZone");

  readonly badgeVariant = computed<"default" | "secondary">(() => {
    return this.status() === "active" ? "default" : "secondary";
  });

  readonly badgeLabel = computed<string>(() => {
    const s = this.status();
    if (s === "intel") return "INTEL";
    if (s === "active") return "DECISION";
    return "DONE";
  });
}

