164→export class RoleCardComponent {
165→  readonly card = input.required<RoleCard>();
166→  readonly systems = input<SystemSnapshot[]>([]);
167→  readonly readonly = input(false);
168→  readonly submitted = output<RoleCardSubmission>();
169→
170→  readonly selectedOptions = signal<string[]>([]);
171→  readonly freeText = signal("");
172→  readonly targetSystemSelections = signal<Record<string, string>>({});
173→
174→  private readonly resetOnCardChange = effect(() => {
175→    this.card();
176→    untracked(() => {
177→      this.selectedOptions.set([]);
178→      this.freeText.set("");
179→      this.targetSystemSelections.set({});
180→    });
181→  });
182→
183→  readonly filteredOptions = computed<DecisionOption[]>(() => {
184→    const decision = this.card().decision;
185→    if (!decision) return [];
186→    const playerType = this.card().playerType;
187→    const roleId = this.card().roleId;
188→    if (playerType === "decision_maker") {
189→      return decision.options;
190→    }
191→    // advisor: COMMON options (no role) + own-role options
192→    return decision.options.filter((o) => !o.role || o.role === roleId);
193→  });
194→
195→  readonly badgeLabel = computed<string>(() => {
196→    const status = this.card().status;
197→    if (status === "intel") return "INTEL";
198→    if (status === "active") return "DECISION";
199→    return "DONE";
200→  });
201→
202→  readonly questionType = computed<string>(() => {
203→    return this.card().decision?.question_type ?? "free_text";
204→  });
205→
206→  readonly doneLabel = computed<string>(() => {
207→    const decision = this.card().decision;
208→    if (!decision) return "";
209→    const roleId = this.card().roleId;
210→    const recEntry = Object.entries(decision.recommendations).find(
211→      ([key]) => extractRecRoleId(key) === roleId,
212→    );
213→    const optionId = recEntry?.[1];
214→    if (!optionId) return "";
215→    return decision.options.find((o) => o.id === optionId)?.label ?? optionId;
216→  });
217→
218→  readonly pendingLabel = computed(() => {
219→    if (!this.readonly()) return null;
220→    const recs = this.card().decision?.recommendations ?? {};
221→    const roleId = this.card().roleId;
222→    const hasRec = Object.keys(recs).some(
223→      (key) => extractRecRoleId(key) === roleId,
224→    );
225→    return hasRec ? null : "pending...";
226→  });
227→
228→  protected isRecommended(optionId: string): boolean {
229→    const recs = this.card().decision?.recommendations ?? {};
230→    return Object.values(recs).includes(optionId);
231→  }
232→
233→  protected isSelected(optionId: string): boolean {
234→    return this.selectedOptions().includes(optionId);
235→  }
236→
237→  protected canSubmit(): boolean {
238→    if (this.questionType() === "free_text") {
239→      return this.freeText().trim().length > 0;
240→    }
241→    if (this.selectedOptions().length === 0) return false;
242→    const opts = this.filteredOptions();
243→    for (const optId of this.selectedOptions()) {
244→      const opt = opts.find((o) => o.id === optId);
245→      if (opt?.targets_system && !this.targetSystemSelections()[optId]) {
246→        return false;
247→      }
248→    }
249→    return true;
250→  }
251→
252→  protected toggleOption(option: DecisionOption): void {
253→    if (this.questionType() === "single_choice") {
254→      this.selectedOptions.set([option.id]);
255→    } else {
256→      const current = this.selectedOptions();
257→      if (current.includes(option.id)) {
258→        this.selectedOptions.set(current.filter((id) => id !== option.id));
259→      } else {
260→        this.selectedOptions.set([...current, option.id]);
261→      }
262→    }
263→  }
264→
265→  protected onSystemSelect(optionId: string, event: Event): void {
266→    const select = event.target;
267→    if (!(select instanceof HTMLSelectElement)) return;
268→    this.targetSystemSelections.update((prev) => ({
269→      ...prev,
270→      [optionId]: select.value,
271→    }));
272→  }
273→
274→  protected onTextInput(event: Event): void {
275→    if (!(event.target instanceof HTMLTextAreaElement)) return;
276→    const textarea = event.target;
277→    this.freeText.set(textarea.value);
278→  }
279→
280→  protected onSubmit(): void {
281→    this.submitted.emit({
282→      roleId: this.card().roleId,
283→      selectedOptions: this.selectedOptions(),
284→      freeText: this.freeText(),
285→      targetSystemSelections: this.targetSystemSelections(),
286→    });
287→  }
288→}
