import { ComponentFixture, TestBed } from "@angular/core/testing";
import { Component, signal } from "@angular/core";
import {
  CoDecisionBarComponent,
  type CoDecisionConfirmation,
} from "./co-decision-bar.component";
import type { ActiveDecision } from "../../core/decision-api.service";
import type { RoleDef } from "../../core/scenario-api.service";
import type { SystemSnapshot } from "../../core/generated/state-changes.types";

function makeDecision(
  overrides: Partial<ActiveDecision> = {},
): ActiveDecision {
  return {
    id: "d1",
    event_id: "e1",
    issue_id: null,
    title: "Respond to threat",
    description: "",
    question_type: "single_choice",
    options: [
      { id: "opt1", label: "Option A" },
      { id: "opt2", label: "Option B" },
      { id: "opt3", label: "Option C" },
    ],
    completion_mode: "any",
    target_roles: ["co", "ops", "nav", "pwo"],
    timeout_ms: 30_000,
    max_selections: null,
    status: "open",
    opened_at_pt_ms: 0,
    closed_at_pt_ms: null,
    recommendations: {},
    selected_option_ids: [],
    ...overrides,
  };
}

const ROLES: RoleDef[] = [
  { id: "ops", label: "Operations", player_type: "advisor" },
  { id: "nav", label: "Navigator", player_type: "advisor" },
  { id: "pwo", label: "Weapons", player_type: "advisor" },
];

@Component({
  imports: [CoDecisionBarComponent],
  template: `
    <tfc-co-decision-bar
      [decision]="decision()"
      [advisorRoles]="advisorRoles()"
      [systems]="systems()"
      (confirmed)="onConfirm($event)"
    />
  `,
})
class TestHost {
  readonly decision = signal<ActiveDecision | null>(makeDecision());
  readonly advisorRoles = signal<RoleDef[]>(ROLES);
  readonly systems = signal<SystemSnapshot[]>([]);
  lastConfirm: CoDecisionConfirmation | null = null;
  onConfirm(e: CoDecisionConfirmation): void {
    this.lastConfirm = e;
  }
}

describe("CoDecisionBarComponent", () => {
  let fixture: ComponentFixture<TestHost>;
  let host: TestHost;

  beforeEach(async () => {
    await TestBed.configureTestingModule({
      imports: [TestHost],
    }).compileComponents();
    fixture = TestBed.createComponent(TestHost);
    host = fixture.componentInstance;
    fixture.detectChanges();
  });

  it("renders all decision options", () => {
    const options = fixture.nativeElement.querySelectorAll(
      ".co-decision-bar__option",
    );
    expect(options.length).toBe(3);
  });

  it("shows empty state when no decision", () => {
    host.decision.set(null);
    fixture.detectChanges();

    const empty = fixture.nativeElement.querySelector(
      ".co-decision-bar__empty",
    );
    expect(empty).toBeTruthy();
    expect(empty.textContent).toContain("Waiting for next decision...");
  });

  it("shows recommendation badges", () => {
    host.decision.set(
      makeDecision({
        recommendations: { "p1:ops": "opt2", "p2:pwo": "opt2" },
      }),
    );
    fixture.detectChanges();

    const badges = fixture.nativeElement.querySelectorAll(
      ".co-decision-bar__rec-badge",
    );
    expect(badges.length).toBeGreaterThan(0);

    // Find opt2 card (second option)
    const options = fixture.nativeElement.querySelectorAll(
      ".co-decision-bar__option",
    );
    const opt2Text = options[1].textContent;
    expect(opt2Text).toContain("Operations");
    expect(opt2Text).toContain("Weapons");
  });

  it("enables confirm after selecting an option", () => {
    const firstOption = fixture.nativeElement.querySelector(
      ".co-decision-bar__option",
    ) as HTMLElement;
    firstOption.click();
    fixture.detectChanges();

    const btn = fixture.nativeElement.querySelector(
      ".co-decision-bar__confirm",
    ) as HTMLButtonElement;
    expect(btn.disabled).toBe(false);
  });

  it("disables confirm with no selection", () => {
    const btn = fixture.nativeElement.querySelector(
      ".co-decision-bar__confirm",
    ) as HTMLButtonElement;
    expect(btn.disabled).toBe(true);
  });

  it("emits confirmed with selected option ids", () => {
    const firstOption = fixture.nativeElement.querySelector(
      ".co-decision-bar__option",
    ) as HTMLElement;
    firstOption.click();
    fixture.detectChanges();

    const btn = fixture.nativeElement.querySelector(
      ".co-decision-bar__confirm",
    ) as HTMLButtonElement;
    btn.click();
    fixture.detectChanges();

    expect(host.lastConfirm).toBeTruthy();
    expect(host.lastConfirm!.selectedOptionIds).toEqual(["opt1"]);
  });
});

import {
  ChangeDetectionStrategy,
  Component,
  computed,
  effect,
  input,
  output,
  signal,
  untracked,
} from "@angular/core";
import { ButtonDirective } from "@aspect/ui";
import type { ActiveDecision } from "../../core/decision-api.service";
import type { RoleDef } from "../../core/scenario-api.service";
import type { SystemSnapshot } from "../../core/generated/state-changes.types";
import { extractRecRoleId } from "./role-card.types";

export interface CoDecisionConfirmation {
  selectedOptionIds: string[];
  targetSystemSelections: Record<string, string>;
}

@Component({
  selector: "tfc-co-decision-bar",
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [ButtonDirective],
  template: `
    @if (decision(); as d) {
      <div class="co-decision-bar">
        @if (coIntel()) {
          <div class="co-decision-bar__intel">{{ coIntel() }}</div>
        }
        <div class="co-decision-bar__options">
          @for (option of d.options; track option.id) {
            <div
              class="co-decision-bar__option"
              [class.co-decision-bar__option--selected]="isSelected(option.id)"
              [attr.data-recommended]="
                getRecommenders(option.id).length > 0 ? '' : null
              "
              (click)="toggleOption(option.id)"
            >
              <span class="co-decision-bar__option-label">{{
                option.label
              }}</span>
              @if (getRecommenders(option.id); as recs) {
                @if (recs.length > 0) {
                  <span class="co-decision-bar__rec-badge"
                    >★ {{ recs.join(", ") }}</span
                  >
                }
              }
              @if (option.targets_system && isSelected(option.id)) {
                <select
                  class="role-card__system-picker"
                  [value]="targetSystemSelections()[option.id] || ''"
                  (change)="onSystemSelect(option.id, $event)"
                  (click)="$event.stopPropagation()"
                >
                  <option value="">Select system...</option>
                  @for (sys of systems(); track sys.system_id) {
                    <option [value]="sys.system_id">{{ sys.label }}</option>
                  }
                </select>
              }
            </div>
          }
        </div>
        <button
          class="co-decision-bar__confirm"
          uiButton
          variant="default"
          [disabled]="!canConfirm()"
          (click)="onConfirm()"
        >
          Confirm
        </button>
      </div>
    } @else {
      <div class="co-decision-bar">
        <div class="co-decision-bar__empty">
          Waiting for next decision...
        </div>
      </div>
    }
  `,
})
export class CoDecisionBarComponent {
  readonly decision = input<ActiveDecision | null>(null);
  readonly advisorRoles = input<RoleDef[]>([]);
  readonly systems = input<SystemSnapshot[]>([]);
  readonly coIntel = input<string | null>(null);

  readonly confirmed = output<CoDecisionConfirmation>();

  readonly selectedOptionIds = signal<string[]>([]);
  readonly targetSystemSelections = signal<Record<string, string>>({});

  private readonly resetOnDecisionChange = effect(() => {
    this.decision();
    untracked(() => {
      this.selectedOptionIds.set([]);
      this.targetSystemSelections.set({});
    });
  });

  readonly canConfirm = computed(() => this.selectedOptionIds().length > 0);

  protected isSelected(optionId: string): boolean {
    return this.selectedOptionIds().includes(optionId);
  }

  protected getRecommenders(optionId: string): string[] {
    const d = this.decision();
    if (!d) return [];
    const roles = this.advisorRoles();
    const result: string[] = [];
    for (const [key, recOptionId] of Object.entries(d.recommendations)) {
      if (recOptionId === optionId) {
        const roleId = extractRecRoleId(key);
        const role = roles.find((r) => r.id === roleId);
        result.push(role?.label ?? roleId.toUpperCase());
      }
    }
    return result;
  }

  protected toggleOption(optionId: string): void {
    const d = this.decision();
    if (!d) return;
    if (d.question_type === "single_choice") {
      this.selectedOptionIds.set([optionId]);
    } else {
      const current = this.selectedOptionIds();
      if (current.includes(optionId)) {
        this.selectedOptionIds.set(current.filter((id) => id !== optionId));
      } else {
        this.selectedOptionIds.set([...current, optionId]);
      }
    }
  }

  protected onSystemSelect(optionId: string, event: Event): void {
    const select = event.target;
    if (!(select instanceof HTMLSelectElement)) return;
    this.targetSystemSelections.update((prev) => ({
      ...prev,
      [optionId]: select.value,
    }));
  }

  protected onConfirm(): void {
    this.confirmed.emit({
      selectedOptionIds: this.selectedOptionIds(),
      targetSystemSelections: this.targetSystemSelections(),
    });
  }
}

