You are implementing Tasks 5 and 6 together: Wire the crew layout AND CO layout into the player view.

These tasks modify the same files so they must be done together.

## Task 5: Crew layout (all_advisors)

## Task 6: CO layout (decision_maker)

**Files to modify:**
- `apps/tfc/frontend/src/app/features/player/player-view.ts`
- `apps/tfc/frontend/src/app/features/player/player-view.html`

## Step 1: Read the current files

Read both `player-view.ts` and `player-view.html` first to understand the current state.

## Step 2: Changes to player-view.ts

Add these imports at the top:

```typescript
import { BoardColumnComponent } from "./board-column.component";
import { CoDecisionBarComponent, type CoDecisionConfirmation } from "./co-decision-bar.component";
import { extractRecRoleId, type RoleCard } from "./role-card.types";
```

Note: `buildRoleCards` is already imported from `./role-card.types`. Just add `extractRecRoleId` and `type RoleCard` to that existing import.

Add `BoardColumnComponent` and `CoDecisionBarComponent` to the `imports` array in the `@Component` decorator.

Add these members to the `PlayerView` class:

```typescript
  protected readonly focusedColumn = signal<number | null>(null);

  protected toggleFocus(index: number): void {
    this.focusedColumn.update((current) => current === index ? null : index);
  }

  protected readonly advisorRoleCards = computed(() => {
    return this.roleCards().filter((c) => c.playerType === "advisor");
  });

  protected readonly isDecisionMaker = computed(() => {
    const role = this.store.playerRole();
    const allRoles = this.store.context()?.roles ?? [];
    const playerRoleDef = allRoles.find((r) => r.id === role);
    return role === "decision_maker" || playerRoleDef?.player_type === "decision_maker";
  });

  protected readonly coRoleId = computed(() => {
    const allRoles = this.store.context()?.roles ?? [];
    return allRoles.find((r) => r.player_type === "decision_maker")?.id ?? null;
  });

  protected readonly coIntel = computed(() => {
    const event = this.currentTurnEvent();
    const id = this.coRoleId();
    if (!event || !id) return null;
    return event.role_descriptions?.[id] ?? null;
  });

  protected readonly advisorRoles = computed(() => {
    const allRoles = this.store.context()?.roles ?? [];
    return allRoles.filter((r) => r.player_type === "advisor");
  });

  protected readonly mirrorRoleCards = computed(() => {
    const allRoles = this.store.context()?.roles ?? [];
    const advisorRolesList = allRoles.filter((r) => r.player_type === "advisor");
    const event = this.currentTurnEvent();
    const decision = this.activeDecisions()[0] ?? null;
    return buildRoleCards(
      advisorRolesList,
      event,
      decision,
      this.submittedRoles(),
      false,
      allRoles,
    );
  });

  protected getDoneLabel(card: RoleCard): string {
    const decision = card.decision;
    if (!decision) return "";
    const recEntry = Object.entries(decision.recommendations).find(
      ([key]) => extractRecRoleId(key) === card.roleId,
    );
    const optionId = recEntry?.[1];
    if (!optionId) return "";
    return decision.options.find((o) => o.id === optionId)?.label ?? optionId;
  }

  protected onCoDecisionConfirmed(confirmation: CoDecisionConfirmation): void {
    const decision = this.activeDecisions()[0];
    if (!decision) return;
    submitDecision(
      this.decisionApi,
      this.store,
      this.exerciseId(),
      decision,
      {
        roleId: this.coRoleId() ?? "co",
        selectedOptions: confirmation.selectedOptionIds,
        freeText: "",
        targetSystemSelections: confirmation.targetSystemSelections,
      },
    );
  }
```

## Step 3: Changes to player-view.html

Replace the `<div class="board-grid">` block (lines 37-41) with this conditional:

```html
    @if (isMultiRole() && !isDecisionMaker()) {
      <!-- Crew (all_advisors) layout: 3 fixed columns -->
      <div class="board-columns"
           [attr.data-focus]="focusedColumn()">
        @for (card of advisorRoleCards(); track card.roleId; let i = $index) {
          <tfc-board-column
            [roleId]="card.roleId"
            [roleLabel]="card.roleLabel"
            [intel]="card.intel"
            [status]="card.status"
            (headerClicked)="toggleFocus(i)"
          >
            <ng-template #decisionZone>
              @if (card.decision && card.status === 'active') {
                <tfc-role-card
                  [card]="card"
                  [systems]="store.systems()"
                  (submitted)="onRoleCardSubmitted($event)"
                />
              } @else if (card.status === 'done') {
                <div class="board-column__empty">
                  Selected: {{ getDoneLabel(card) }}
                </div>
              } @else {
                <div class="board-column__empty">No active decision</div>
              }
            </ng-template>
          </tfc-board-column>
        }
      </div>
    } @else if (isDecisionMaker()) {
      <!-- CO layout: 3 read-only mirrors + decision bar -->
      <div class="board-columns"
           [attr.data-focus]="focusedColumn()">
        @for (card of mirrorRoleCards(); track card.roleId; let i = $index) {
          <tfc-board-column
            [roleId]="card.roleId"
            [roleLabel]="card.roleLabel"
            [intel]="card.intel"
            [status]="card.status"
            (headerClicked)="toggleFocus(i)"
          >
            <ng-template #decisionZone>
              @if (card.decision && card.status !== 'done') {
                <tfc-role-card
                  [card]="card"
                  [systems]="store.systems()"
                  [readonly]="true"
                  (submitted)="onRoleCardSubmitted($event)"
                />
              } @else if (card.status === 'done') {
                <div class="board-column__empty">
                  Selected: {{ getDoneLabel(card) }}
                </div>
              } @else {
                <div class="board-column__empty">No active decision</div>
              }
            </ng-template>
          </tfc-board-column>
        }
      </div>
      <tfc-co-decision-bar
        [decision]="activeDecisions()[0] ?? null"
        [advisorRoles]="advisorRoles()"
        [systems]="store.systems()"
        [coIntel]="coIntel()"
        (confirmed)="onCoDecisionConfirmed($event)"
      />
    } @else {
      <!-- Single-role or legacy layout -->
      <div class="board-grid">
        @for (card of roleCards(); track card.roleId) {
          <tfc-role-card [card]="card" [systems]="store.systems()" (submitted)="onRoleCardSubmitted($event)" />
        }
      </div>
    }
```

