/* ── Player View — Cyber Supply-Chain Console ────────── */

@layer components {
  .player-layout {
    display: grid;
    grid-template-rows: auto auto 1fr auto;
    height: 100dvh;
    overflow: hidden;
    background: var(--color-background);
    position: relative;
    z-index: 0;
  }
  .player-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-md);
    padding: var(--spacing-sm) var(--spacing-lg);
    background: var(--glass-bg), var(--color-card);
    backdrop-filter: blur(var(--glass-blur));
    -webkit-backdrop-filter: blur(var(--glass-blur));
    border-bottom: 1px solid var(--color-primary);
    box-shadow: var(--glass-shadow), var(--glow-sm);
    position: relative;
  }
  .player-header::after {
    content: "";
    position: absolute;
    inset: 0;
    background: repeating-linear-gradient(
      0deg,
      transparent,
      transparent 2px,
      oklch(0% 0 0 / 8%) 2px,
      oklch(0% 0 0 / 8%) 4px
    );
    pointer-events: none;
  }
  .player-header__title {
    font-family: var(--font-mono);
    font-size: var(--font-size-lg);
    font-weight: 700;
    color: var(--color-primary);
    text-transform: uppercase;
    letter-spacing: 0.08em;
  }
  .player-header > .stress-bar {
    flex: 1;
  }
  .player-header__clocks {
    display: flex;
    gap: var(--spacing-lg);
    align-items: center;
  }
  .player-footer {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
    padding: var(--spacing-xs) var(--spacing-lg);
    border-top: 1px solid var(--color-border);
    background: var(--color-card);
    font-family: var(--font-mono);
    font-size: var(--font-size-xs);
    color: var(--color-muted-foreground);
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }
  .player-footer__group {
    display: flex;
    gap: var(--spacing-sm);
    align-items: center;
  }
  .player-main {
    overflow-y: auto;
    padding: var(--spacing-md) var(--spacing-lg);
    display: flex;
    flex-direction: column;
    gap: var(--spacing-lg);
    background: var(--color-background);
  }
  .player-main__columns {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-md);
  }
  .event-tile {
    display: flex;
    align-items: flex-start;
    gap: var(--spacing-sm);
    padding: var(--spacing-sm) var(--spacing-md);
    border: 1px solid var(--color-border);
    border-left: 3px solid var(--color-primary);
    border-radius: 2px;
    background: var(--color-card);
    box-shadow: var(--glow-sm);
    transition:
      box-shadow 200ms ease,
      border-color 200ms ease;
  }
  .event-tile:hover {
    border-color: var(--color-primary);
    box-shadow: var(--glow-primary);
  }
  .event-tile__icon {
    --icon-size: 2rem;
    flex-shrink: 0;
    width: var(--icon-size);
    height: var(--icon-size);
    border-radius: 2px;
    background: var(--color-primary);
    color: var(--color-primary-foreground);
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: var(--font-mono);
    font-size: var(--font-size-xs);
    font-weight: 700;
    text-transform: uppercase;
  }
  .event-tile__body {
    flex: 1;
    min-width: 0;
  }
  .event-tile__title {
    font-family: var(--font-mono);
    font-size: var(--font-size-sm);
    font-weight: 600;
    color: var(--color-foreground);
  }
  .event-tile__desc {
    font-size: var(--font-size-xs);
    color: var(--color-muted-foreground);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    margin-top: var(--spacing-2xs);
  }
  .event-tile__meta {
    display: flex;
    gap: var(--spacing-xs);
    margin-top: var(--spacing-xs);
  }
  .issue-tile {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-sm);
    padding: var(--spacing-sm) var(--spacing-md);
    border: 1px solid var(--color-border);
    border-left: 3px solid var(--color-muted);
    border-radius: 2px;
    background: var(--color-card);
    cursor: pointer;
    transition:
      box-shadow 200ms ease,
      border-color 200ms ease;
  }
  .issue-tile:hover {
    border-color: var(--color-primary);
    box-shadow: var(--glow-sm);
  }
  .issue-tile[data-lifecycle="active"] {
    border-left-color: var(--color-destructive);
    box-shadow:
      inset 0 0 12px oklch(65% 0.25 25 / 8%),
      var(--glow-sm);
    animation: threat-pulse 1.5s ease-in-out infinite;
  }
  .issue-tile[data-lifecycle="mitigated"] {
    border-left-color: var(--color-warning);
  }
  .issue-tile[data-lifecycle="resolved"] {
    border-left-color: var(--color-success);
    opacity: 0.5;
  }
  @keyframes threat-pulse {
    0%,
    100% {
      border-left-color: var(--color-destructive);
      box-shadow:
        inset 0 0 12px oklch(65% 0.25 25 / 8%),
        var(--glow-sm);
    }
    50% {
      border-left-color: oklch(70% 0.28 25);
      box-shadow:
        inset 0 0 20px oklch(65% 0.25 25 / 15%),
        0 0 18px oklch(65% 0.25 25 / 30%);
    }
  }
  .issue-tile__body {
    flex: 1;
    min-width: 0;
  }
  .issue-tile__title {
    font-family: var(--font-mono);
    font-size: var(--font-size-sm);
    font-weight: 600;
    color: var(--color-foreground);
  }
  .issue-tile__desc {
    font-size: var(--font-size-xs);
    color: var(--color-muted-foreground);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    margin-top: var(--spacing-2xs);
  }
  .issue-tile__countdown {
    font-family: var(--font-mono);
    font-size: var(--font-size-xs);
    font-variant-numeric: tabular-nums;
    color: var(--color-destructive);
    white-space: nowrap;
    animation: countdown-blink 1s step-end infinite;
  }
  @keyframes countdown-blink {
    0%,
    100% {
      opacity: 1;
    }
    50% {
      opacity: 0.4;
    }
  }
  .issue-detail {
    padding: var(--spacing-md);
    border-radius: 2px;
    background: var(--color-card);
    border: 1px solid var(--color-primary);
    box-shadow: var(--glow-sm);
  }
  .issue-detail__badges {
    display: flex;
    gap: var(--spacing-sm);
    margin-top: var(--spacing-md);
  }
  .empty-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--spacing-xs);
    padding: var(--spacing-xl) var(--spacing-md);
    color: var(--color-muted-foreground);
  }
  .empty-state__icon {
    font-family: var(--font-mono);
    font-size: var(--font-size-lg);
    color: var(--color-primary);
    opacity: 0.4;
  }
  .empty-state__text {
    font-family: var(--font-mono);
    font-size: var(--font-size-xs);
    text-align: center;
    text-transform: uppercase;
    letter-spacing: 0.06em;
  }

  @media (prefers-reduced-motion: reduce) {
    .issue-tile[data-lifecycle="active"] {
      animation: none;
    }
    .issue-tile__countdown {
      animation: none;
    }
  }

  /* ── Board Layout ──────────────────────────────────── */

  .player-main--board {
    padding: 0;
    gap: 0;
  }

  .board-turn-banner {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
    padding: var(--spacing-xs) var(--spacing-lg);
    border-bottom: 1px solid var(--color-border);
  }
  .board-turn-banner__turn {
    font-family: var(--font-mono);
    font-size: var(--font-size-lg);
    font-weight: 700;
    color: var(--color-accent);
    letter-spacing: 0.05em;
    flex-shrink: 0;
  }
  .board-turn-banner__title {
    font-family: var(--font-mono);
    font-size: var(--font-size-lg);
    font-weight: 600;
    color: var(--color-foreground);
  }
  .board-turn-banner__title::after {
    content: none;
  }
  .board-turn-banner__desc {
    display: none;
  }

  .board-grid {
    display: flex;
    flex-wrap: wrap;
    gap: var(--spacing-md);
    padding: var(--spacing-md) var(--spacing-lg);
  }

  /* ── Board Columns (3-column fixed layout) ─────────── */

  .board-columns {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: var(--spacing-md);
    padding: var(--spacing-md) var(--spacing-lg);
    flex: 1;
    min-height: 0;
    transition: grid-template-columns 200ms ease;
  }

  /* Focus mode — expand one column, shrink others */
  .board-columns[data-focus="0"] { grid-template-columns: 2fr 0.5fr 0.5fr; }
  .board-columns[data-focus="1"] { grid-template-columns: 0.5fr 2fr 0.5fr; }
  .board-columns[data-focus="2"] { grid-template-columns: 0.5fr 0.5fr 2fr; }

  /* ── Board Column (single role column) ──────────────── */

  .board-column {
    display: grid;
    grid-template-rows: auto 2fr 3fr;
    min-height: 0;
    overflow: hidden;
    border: 1px solid var(--color-border);
    border-radius: 2px;
    background: var(--color-card);
  }

  .board-column__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: var(--spacing-sm) var(--spacing-md);
    border-bottom: 1px solid var(--color-border);
    cursor: pointer;
    user-select: none;
  }

  .board-column__header:hover {
    background: var(--color-secondary);
  }

  .board-column__role-id {
    font-family: var(--font-mono);
    font-size: var(--font-size-sm);
    font-weight: 700;
    color: var(--color-primary);
  }

  .board-column__role-label {
    font-size: var(--font-size-xs);
    color: var(--color-muted-foreground);
    font-style: italic;
  }

  .board-column__intel {
    overflow-y: auto;
    padding: var(--spacing-md);
    border-bottom: 1px solid var(--color-border);
  }

  .board-column__decision {
    overflow-y: auto;
    padding: var(--spacing-md);
  }

  /* Empty state text for zones */
  .board-column__empty {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: var(--color-muted-foreground);
    font-family: var(--font-mono);
    font-size: var(--font-size-xs);
    text-transform: uppercase;
    letter-spacing: 0.06em;
  }

  /* Shrunk column in focus mode — hide role label, truncate intel */
  .board-columns[data-focus] .board-column .board-column__role-label {
    display: none;
  }

  .board-columns[data-focus="0"] .board-column:nth-child(1) .board-column__role-label,
  .board-columns[data-focus="1"] .board-column:nth-child(2) .board-column__role-label,
  .board-columns[data-focus="2"] .board-column:nth-child(3) .board-column__role-label {
    display: block;
  }

  .board-columns[data-focus] .board-column .board-column__intel {
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  /* Restore scroll on the focused column */
  .board-columns[data-focus="0"] .board-column:nth-child(1) .board-column__intel,
  .board-columns[data-focus="1"] .board-column:nth-child(2) .board-column__intel,
  .board-columns[data-focus="2"] .board-column:nth-child(3) .board-column__intel {
    overflow-y: auto;
    white-space: normal;
  }

  /* ── Role Card ─────────────────────────────────────── */

  .role-card {
    flex: 1 1 14rem;
    max-width: 22rem;
    display: flex;
    flex-direction: column;
    padding: var(--spacing-md);
    border-radius: 2px;
    background: var(--color-card);
    border: 1px solid var(--color-border);
    transition:
      box-shadow 200ms ease,
      border-color 200ms ease,
      opacity 200ms ease;
  }
  .role-card--intel {
    border-left: 3px solid var(--color-primary);
  }
  .role-card--active {
    border: 2px solid var(--color-success);
    background: color-mix(
      in oklch,
      var(--color-success) 10%,
      var(--color-card)
    );
  }
  .role-card--done {
    border: 1px solid var(--color-muted);
    opacity: 0.7;
  }

  .role-card__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: var(--spacing-2xs);
  }
  .role-card__role-id {
    font-family: var(--font-mono);
    font-size: var(--font-size-sm);
    font-weight: 700;
    color: var(--color-primary);
  }
  .role-card--active .role-card__role-id {
    color: var(--color-success);
  }
  .role-card__role-label {
    font-size: var(--font-size-xs);
    color: var(--color-muted-foreground);
    font-style: italic;
    margin-bottom: var(--spacing-sm);
  }

  .role-card__intel {
    font-size: var(--font-size-sm);
    color: var(--color-foreground);
    line-height: 1.5;
    margin-bottom: var(--spacing-sm);
  }
  .role-card__intel--empty {
    color: var(--color-muted-foreground);
    font-style: italic;
  }

  /* ── Advisor Recs ──────────────────────────────────── */

  .role-card__recs {
    margin-bottom: var(--spacing-sm);
    display: flex;
    flex-direction: column;
    gap: var(--spacing-2xs);
  }
  .role-card__recs-title {
    font-size: var(--font-size-xs);
    color: var(--color-primary);
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: var(--spacing-2xs);
  }
  .role-card__rec {
    padding: var(--spacing-xs) var(--spacing-sm);
    background: var(--color-card);
    border-radius: 2px;
    border-left: 2px solid var(--color-primary);
    font-size: var(--font-size-xs);
  }
  .role-card__rec--pending {
    border-left-style: dashed;
    border-left-color: var(--color-muted);
  }
  .role-card__rec-role {
    color: var(--color-primary);
    font-weight: 600;
  }
  .role-card__rec-selection {
    color: var(--color-muted-foreground);
  }
  .role-card__rec-pending {
    color: var(--color-muted);
    font-style: italic;
  }

  /* ── Decision Form ─────────────────────────────────── */

  .role-card__decision {
    border-top: 1px solid var(--color-success);
    padding-top: var(--spacing-sm);
    margin-top: auto;
    display: flex;
    flex-direction: column;
    gap: var(--spacing-xs);
  }
  .role-card__decision-question {
    font-size: var(--font-size-xs);
    color: var(--color-success);
    font-weight: 600;
    margin-bottom: var(--spacing-2xs);
  }
  .role-card__option {
    display: flex;
    align-items: center;
    gap: var(--spacing-xs);
    padding: var(--spacing-xs) var(--spacing-sm);
    border: 1px solid var(--color-border);
    border-radius: 2px;
    cursor: pointer;
    font-size: var(--font-size-xs);
    color: var(--color-foreground);
    transition: background 150ms ease;
  }
  .role-card__option:hover {
    background: var(--color-secondary);
  }
  .role-card__option--selected {
    background: var(--color-secondary);
    border-color: var(--color-success);
  }
  .role-card__system-picker {
    width: 100%;
    margin-top: var(--spacing-2xs);
    padding: var(--spacing-2xs) var(--spacing-xs);
    border: 1px solid var(--color-border);
    border-radius: 2px;
    background: var(--color-input);
    color: var(--color-foreground);
    font-size: var(--font-size-xs);
    font-family: var(--font-mono);
  }
  .role-card__system-picker:focus {
    outline: 2px solid var(--color-ring);
    outline-offset: 1px;
  }
  .role-card__textarea {
    width: 100%;
    min-height: calc(var(--spacing-xl) * 2);
    padding: var(--spacing-xs);
    border: 1px solid var(--color-border);
    border-radius: 2px;
    background: var(--color-input);
    color: var(--color-foreground);
    font-size: var(--font-size-xs);
    font-family: inherit;
    resize: vertical;
  }
  .role-card__textarea:focus {
    outline: 2px solid var(--color-ring);
    outline-offset: 1px;
  }
  .role-card__actions {
    display: flex;
    justify-content: flex-end;
    margin-top: var(--spacing-xs);
  }

  .role-card__done {
    border-top: 1px solid var(--color-muted);
    padding-top: var(--spacing-xs);
    margin-top: auto;
    font-size: var(--font-size-xs);
    color: var(--color-muted-foreground);
  }

  /* ── CO Decision Bar ─────────────────────────────── */

  .co-decision-bar {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
    padding: var(--spacing-md) var(--spacing-lg);
    border-top: 2px solid var(--color-success);
    background: color-mix(in oklch, var(--color-success) 5%, var(--color-card));
    flex-shrink: 0;
  }

  .co-decision-bar__options {
    display: flex;
    flex: 1;
    gap: var(--spacing-sm);
    flex-wrap: wrap;
  }

  .co-decision-bar__option {
    flex: 1 1 0;
    display: flex;
    flex-direction: column;
    gap: var(--spacing-2xs);
    padding: var(--spacing-sm) var(--spacing-md);
    border: 1px solid var(--color-border);
    border-radius: 2px;
    cursor: pointer;
    font-size: var(--font-size-sm);
    color: var(--color-foreground);
    transition: background 150ms ease, border-color 150ms ease;
  }

  .co-decision-bar__option:hover {
    background: var(--color-secondary);
  }

  .co-decision-bar__option--selected {
    background: var(--color-secondary);
    border-color: var(--color-success);
  }

  .co-decision-bar__option[data-recommended] {
    border-color: var(--color-primary);
    box-shadow: var(--glow-sm);
  }

  .co-decision-bar__option-label {
    font-weight: 500;
  }

  .co-decision-bar__rec-badge {
    font-family: var(--font-mono);
    font-size: var(--font-size-xs);
    color: var(--color-primary);
    font-weight: 600;
  }

  .co-decision-bar__empty {
    flex: 1;
    text-align: center;
    color: var(--color-muted-foreground);
    font-family: var(--font-mono);
    font-size: var(--font-size-xs);
    text-transform: uppercase;
    letter-spacing: 0.06em;
  }

  .co-decision-bar__intel {
    font-size: var(--font-size-sm);
    color: var(--color-muted-foreground);
    font-style: italic;
    padding-right: var(--spacing-md);
    border-right: 1px solid var(--color-border);
  }

  /* ── Responsive: large monitor ──────────────────────── */
  @media (min-width: 1920px) {
    .board-columns {
      max-width: 1600px;
      margin-inline: auto;
    }
  }

  /* ── Responsive: narrow laptop ──────────────────────── */
  @media (max-width: 1280px) {
    .board-column__header {
      padding: var(--spacing-xs) var(--spacing-sm);
    }
    .board-column__intel,
    .board-column__decision {
      padding: var(--spacing-sm);
    }
    .board-column__role-id {
      font-size: var(--font-size-xs);
    }
  }

  /* ── Responsive: fallback (< 1024px) ────────────────── */
  @media (max-width: 1024px) {
    .board-columns {
      grid-template-columns: 1fr;
    }
    .board-columns[data-focus="0"],
    .board-columns[data-focus="1"],
    .board-columns[data-focus="2"] {
      grid-template-columns: 1fr;
    }
  }
}

